function cr_https(){return (!empty($_SERVER['HTTPS'])&&strtolower($_SERVER['HTTPS'])!=='off')||(!empty($_SERVER['HTTP_X_FORWARDED_PROTO'])&&strtolower($_SERVER['HTTP_X_FORWARDED_PROTO'])==='https');}
function cr_clean($v,$n){$v=trim((string)$v);return function_exists('mb_substr')?mb_substr($v,0,$n,'UTF-8'):substr($v,0,$n);}
function cr_now(){return date('Y-m-d H:i:s');}
function cr_send($d,$status){http_response_code($status);header('Content-Type: application/json; charset=UTF-8');header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');header('Pragma: no-cache');header('X-Content-Type-Options: nosniff');echo json_encode($d,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
function cr_ok($d){if(!is_array($d))$d=array();$d['ok']=true;cr_send($d,200);}
function cr_err($m,$s){cr_send(array('ok'=>false,'error'=>$m),$s);}
function cr_body(){$raw=file_get_contents('php://input');if($raw===false||trim($raw)==='')return array();$d=json_decode($raw,true);if(!is_array($d))cr_err('Geçersiz istek verisi.',400);return $d;}
function cr_auth_header(){if(!empty($_SERVER['HTTP_AUTHORIZATION']))return trim($_SERVER['HTTP_AUTHORIZATION']);if(!empty($_SERVER['REDIRECT_HTTP_AUTHORIZATION']))return trim($_SERVER['REDIRECT_HTTP_AUTHORIZATION']);return '';}
function cr_bearer(){$h=cr_auth_header();if(preg_match('/^Bearer\s+([A-Za-z0-9,-]{16,160})$/i',$h,$m))return $m[1];return '';}
function cr_session_start($token){session_name('ELAKCORESESSID');session_set_cookie_params(0,'/','',cr_https(),true);if($token!==''){@session_id($token);}@session_start();}
function cr_json_array($v){if(is_array($v))return $v;$x=json_decode((string)$v,true);return is_array($x)?$x:array();}
function cr_module_ok($org){$mods=cr_json_array(isset($org['modules'])?$org['modules']:array());if(!count($mods))return true;return in_array('akilli_rehber',$mods,true)||in_array('rehber',$mods,true);}
function cr_license_ok($o){return $o&&!empty($o['status'])&&!empty($o['expiry'])&&strtotime($o['expiry'])>=time()&&cr_module_ok($o);}
function cr_org_by_code($code){$q=elak_db()->prepare('SELECT * FROM `'.elak_table('organizations').'` WHERE org_code=? LIMIT 1');$q->execute(array($code));return $q->fetch();}
function cr_has($k){if(!empty($_SESSION['legacy_org_admin']))return true;$p=isset($_SESSION['permissions'])&&is_array($_SESSION['permissions'])?$_SESSION['permissions']:array();return !empty($p['*'])||!empty($p[$k]);}
function cr_can_edit(){return cr_has('users.manage')||cr_has('settings.manage');}
function cr_require(){if(empty($_SESSION['org_id']))cr_err('Oturum süresi dolmuş. ELAK Okulum üzerinden tekrar giriş yapın.',401);$q=elak_db()->prepare('SELECT * FROM `'.elak_table('organizations').'` WHERE id=? LIMIT 1');$q->execute(array((int)$_SESSION['org_id']));$o=$q->fetch();if(!cr_license_ok($o))cr_err('Kurum lisansı veya Akıllı Rehber modülü aktif değil.',403);if(!empty($_SESSION['user_id'])){$q=elak_db()->prepare('SELECT active FROM `'.elak_table('users').'` WHERE id=? AND org_id=? LIMIT 1');$q->execute(array((int)$_SESSION['user_id'],(int)$_SESSION['org_id']));if((int)$q->fetchColumn()!==1)cr_err('Kullanıcı hesabı pasif.',403);$rk=isset($_SESSION['role_key'])?(string)$_SESSION['role_key']:'';$allowed=in_array($rk,array('admin','manager','teacher','guidance'),true)||cr_has('users.view')||cr_has('settings.view');if(!$allowed)cr_err('Akıllı Rehber erişim yetkiniz yok.',403);}return $o;}
function cr_phone($v){$d=preg_replace('/\D+/','',(string)$v);if(strlen($d)>=12&&substr($d,0,2)==='90')$d=substr($d,2);if(strlen($d)===11&&substr($d,0,1)==='0')$d=substr($d,1);return substr($d,0,20);}
function cr_photo_root(){return dirname(__FILE__).'/storage/student-photos';}
function cr_photo_abs($rel){$rel=str_replace(array('..','\\'),'',(string)$rel);return cr_photo_root().'/'.$rel;}
function cr_photo_info($path){$i=@getimagesize($path);if(!$i||empty($i[2]))return null;if($i[2]===IMAGETYPE_JPEG)return array('ext'=>'jpg','mime'=>'image/jpeg');if($i[2]===IMAGETYPE_PNG)return array('ext'=>'png','mime'=>'image/png');return null;}
function cr_photo_dir($org){$root=cr_photo_root();if(!is_dir($root)&&!@mkdir($root,0755,true))cr_err('Fotoğraf klasörü oluşturulamadı.',500);$deny=$root.'/.htaccess';if(!is_file($deny))@file_put_contents($deny,"Deny from all\n<IfModule mod_authz_core.c>\nRequire all denied\n</IfModule>\n",LOCK_EX);$d=$root.'/'.(int)$org;if(!is_dir($d)&&!@mkdir($d,0755,true))cr_err('Kurum fotoğraf klasörü oluşturulamadı.',500);return $d;}
function cr_revision($org){$db=elak_db();$max='';$queries=array(
 'SELECT MAX(updated_at) FROM `'.elak_table('data_classes').'` WHERE org_id=?',
 'SELECT MAX(updated_at) FROM `'.elak_table('data_students').'` WHERE org_id=?',
 'SELECT MAX(updated_at) FROM `'.elak_table('data_guardians').'` WHERE org_id=?',
 'SELECT MAX(updated_at) FROM `'.elak_table('data_student_guardians').'` WHERE org_id=?'
 );foreach($queries as $sql){try{$q=$db->prepare($sql);$q->execute(array($org));$v=(string)$q->fetchColumn();if($v!==''&&($max===''||$v>$max))$max=$v;}catch(Exception $e){}}return $max!==''?(string)strtotime($max):'0';}
function cr_announcements($org){try{$now=cr_now();$sql='SELECT id,title,body,level,created_at FROM `'.elak_table('announcements').'` WHERE active=1 AND (org_id IS NULL OR org_id=?) AND (starts_at IS NULL OR starts_at<=?) AND (ends_at IS NULL OR ends_at>=?) ORDER BY id DESC LIMIT 20';$q=elak_db()->prepare($sql);$q->execute(array($org,$now,$now));$out=array();foreach($q->fetchAll() as $r){$body=(string)$r['body'];$summary=function_exists('mb_substr')?mb_substr($body,0,220,'UTF-8'):substr($body,0,220);$out[]=array('id'=>(string)$r['id'],'title'=>$r['title'],'summary'=>$summary,'body'=>$body,'published_at'=>$r['created_at'],'priority'=>isset($r['level'])?$r['level']:'info');}return $out;}catch(Exception $e){return array();}}
function cr_user_payload(){return array('id'=>!empty($_SESSION['user_id'])?(int)$_SESSION['user_id']:0,'display_name'=>isset($_SESSION['user_name'])?$_SESSION['user_name']:'Kurum Yöneticisi','name'=>isset($_SESSION['user_name'])?$_SESSION['user_name']:'Kurum Yöneticisi','role'=>isset($_SESSION['role_name'])?$_SESSION['role_name']:'Kurum Yöneticisi','role_key'=>isset($_SESSION['role_key'])?$_SESSION['role_key']:'admin');}
