 $q=$db->prepare('SELECT sg.student_id,g.id guardian_id,g.full_name,g.phone,sg.relationship,sg.is_primary FROM `'.$sgt.'` sg INNER JOIN `'.$gt.'` g ON g.id=sg.guardian_id AND g.org_id=sg.org_id WHERE sg.org_id=? AND g.active=1 ORDER BY sg.student_id,sg.is_primary DESC,sg.id');$q->execute(array($org));$gmap=array();foreach($q->fetchAll() as $g){$sid=(int)$g['student_id'];if(!isset($gmap[$sid]))$gmap[$sid]=array();$gmap[$sid][]=array('id'=>(int)$g['guardian_id'],'guardian_id'=>(int)$g['guardian_id'],'name'=>$g['full_name'],'guardian_name'=>$g['full_name'],'relationship'=>$g['relationship'],'phone'=>cr_phone($g['phone']),'is_primary'=>(int)$g['is_primary']?true:false);}
 $q=$db->prepare('SELECT s.id,s.school_no,s.full_name,s.class_id,c.name class_name,s.school_type,s.gender,s.boarding_status,s.phone,s.photo_path,s.photo_updated_at FROM `'.$st.'` s LEFT JOIN `'.$ct.'` c ON c.id=s.class_id AND c.org_id=s.org_id WHERE s.org_id=? AND s.active=1 ORDER BY c.name,s.full_name');$q->execute(array($org));$students=array();$entries=array();$editable=cr_can_edit();foreach($q->fetchAll() as $s){$sid=(int)$s['id'];$pv=!empty($s['photo_updated_at'])?strtotime($s['photo_updated_at']):0;$guardians=isset($gmap[$sid])?$gmap[$sid]:array();$item=array('student_id'=>$sid,'id'=>$sid,'student_name'=>$s['full_name'],'name'=>$s['full_name'],'full_name'=>$s['full_name'],'school_no'=>$s['school_no'],'class_id'=>!empty($s['class_id'])?(int)$s['class_id']:0,'class_name'=>isset($s['class_name'])?(string)$s['class_name']:'','student_phone'=>cr_phone($s['phone']),'phone'=>cr_phone($s['phone']),'school_type'=>(string)$s['school_type'],'gender'=>(string)$s['gender'],'boarding_status'=>(string)$s['boarding_status'],'has_photo'=>!empty($s['photo_path']),'photo_version'=>$pv,'can_edit'=>$editable,'guardians'=>$guardians);$students[]=$item;
   $studentObj=array('id'=>$sid,'student_id'=>$sid,'name'=>$s['full_name'],'school_no'=>$s['school_no'],'class_name'=>$item['class_name'],'phone'=>$item['student_phone'],'has_photo'=>$item['has_photo'],'photo_version'=>$pv);
   if(strlen($item['student_phone'])>=10){$entries[]=array('phone'=>$item['student_phone'],'label'=>'Öğrenci','student_id'=>$sid,'student_name'=>$s['full_name'],'school_no'=>$s['school_no'],'class_name'=>$item['class_name'],'relationship'=>'Öğrenci','guardian_name'=>'','has_photo'=>$item['has_photo'],'photo_version'=>$pv,'student'=>$studentObj);}
