 }
 return array('students_summary'=>$students,'students'=>$students,'classes'=>$classes,'entries'=>$entries,'announcements'=>cr_announcements($org),'revision'=>cr_revision($org),'user'=>cr_user_payload(),'school_scope'=>'both','mobile_access'=>'both','source'=>'ELAK Kurum Veri Merkezi');
}
function cr_login($in){$db=elak_db();$code=strtoupper(cr_clean(isset($in['code'])?$in['code']:(isset($in['org_code'])?$in['org_code']:''),80));$username=cr_clean(isset($in['username'])?$in['username']:'',100);$pass=isset($in['password'])?(string)$in['password']:'';if($pass==='')cr_err('Şifre zorunludur.',400);$chosen=null;$user=null;
