 if($user){try{$q=$db->prepare('UPDATE `'.elak_table('users').'` SET last_login=?,updated_at=? WHERE id=?');$q->execute(array(cr_now(),cr_now(),(int)$user['id']));}catch(Exception $e){}}
 cr_ok(array('token'=>session_id(),'name'=>$_SESSION['user_name'],'display_name'=>$_SESSION['user_name'],'role'=>$_SESSION['role_name'],'school_scope'=>'both','org_code'=>$chosen['org_code'],'user'=>cr_user_payload(),'data'=>array('token'=>session_id(),'name'=>$_SESSION['user_name'],'display_name'=>$_SESSION['user_name'],'role'=>$_SESSION['role_name'],'school_scope'=>'both','org_code'=>$chosen['org_code'],'user'=>cr_user_payload())));
}

