 if($api==='student_photo'){if($_SERVER['REQUEST_METHOD']!=='POST')cr_err('POST gerekli.',405);if(!cr_can_edit())cr_err('Fotoğraf güncelleme yetkiniz yok.',403);$in=cr_body();$sid=(int)(isset($in['student_id'])?$in['student_id']:0);$b64=isset($in['photo_base64'])?(string)$in['photo_base64']:'';if(!$sid||$b64==='')cr_err('Öğrenci ve fotoğraf zorunludur.',400);if(strlen($b64)>8*1024*1024)cr_err('Fotoğraf çok büyük.',400);$bin=base64_decode($b64,true);if($bin===false||strlen($bin)>5*1024*1024)cr_err('Fotoğraf verisi geçersiz veya 5 MB sınırını aşıyor.',400);$tmp=tempnam(sys_get_temp_dir(),'elakrehber_');if($tmp===false)cr_err('Geçici dosya oluşturulamadı.',500);file_put_contents($tmp,$bin,LOCK_EX);$info=cr_photo_info($tmp);if(!$info){@unlink($tmp);cr_err('Yalnız JPG veya PNG fotoğraf desteklenir.',400);}$q=elak_db()->prepare('SELECT school_no,photo_path FROM `'.elak_table('data_students').'` WHERE org_id=? AND id=? AND active=1 LIMIT 1');$q->execute(array($org,$sid));$s=$q->fetch();if(!$s){@unlink($tmp);cr_err('Öğrenci bulunamadı.',404);}$safe=preg_replace('/[^A-Za-z0-9_-]+/','_',cr_clean($s['school_no'],40));$dir=cr_photo_dir($org);$rel=$org.'/'.$safe.'.'.$info['ext'];$abs=cr_photo_abs($rel);if(!@copy($tmp,$abs)){@unlink($tmp);cr_err('Fotoğraf kaydedilemedi.',500);}@unlink($tmp);@chmod($abs,0644);if(!empty($s['photo_path'])&&$s['photo_path']!==$rel){$old=cr_photo_abs($s['photo_path']);if(is_file($old))@unlink($old);}elak_db()->prepare('UPDATE `'.elak_table('data_students').'` SET photo_path=?,photo_updated_at=?,updated_at=? WHERE org_id=? AND id=?')->execute(array($rel,cr_now(),cr_now(),$org,$sid));$rev=cr_revision($org);cr_ok(array('data'=>array('updated'=>1,'photo_version'=>(int)$rev),'updated'=>1,'photo_version'=>(int)$rev));}
 if($api==='photo'){$sid=(int)(isset($_GET['id'])?$_GET['id']:0);$q=elak_db()->prepare('SELECT photo_path FROM `'.elak_table('data_students').'` WHERE org_id=? AND id=? AND active=1 LIMIT 1');$q->execute(array($org,$sid));$rel=$q->fetchColumn();if(!$rel)cr_err('Fotoğraf bulunamadı.',404);$abs=cr_photo_abs($rel);if(!is_file($abs))cr_err('Fotoğraf bulunamadı.',404);$info=cr_photo_info($abs);if(!$info)cr_err('Fotoğraf geçersiz.',404);header_remove('Content-Type');header('Content-Type: '.$info['mime']);header('Cache-Control: private, max-age=86400');header('X-Content-Type-Options: nosniff');readfile($abs);exit;}
